1	/* Scoped motion for the /preview/nxcloud template. Net-new, additive. Every
2	   animation is disabled under prefers-reduced-motion. Global pv-* / animate-*
3	   keyframes are reused where they already exist; only new motion lives here. */
4	
5	/* Talk waveform bars */
6	.bar {
7	  transform-origin: center;
8	  animation: nxCloudBar 1.1s ease-in-out infinite;
9	}
10	@keyframes nxCloudBar {
11	  0%,
12	  100% {
13	    transform: scaleY(0.35);
14	  }
15	  50% {
16	    transform: scaleY(1);
17	  }
18	}
19	
20	/* a gently rotating sync glyph */
21	.spin {
22	  animation: nxCloudSpin 2.4s linear infinite;
23	}
24	@keyframes nxCloudSpin {
25	  to {
26	    transform: rotate(360deg);
27	  }
28	}
29	
30	/* file/feature rows stagger in (used with inline animation-delay) */
31	.row {
32	  animation: nxCloudRow 0.45s cubic-bezier(0.22, 1, 0.36, 1) both;
33	}
34	@keyframes nxCloudRow {
35	  from {
36	    opacity: 0;
37	    transform: translateY(8px);
38	  }
39	  to {
40	    opacity: 1;
41	    transform: translateY(0);
42	  }
