42	function fnv(s: string): number {
43	  let h = 2166136261;
44	  for (let i = 0; i < s.length; i++) {
45	    h ^= s.charCodeAt(i);
46	    h = (h * 16777619) >>> 0;
47	  }
48	  return h;
49	}
