51	function buildMock(host: string, port: number): MockResult {
52	  const h = fnv(host.toLowerCase() || "play.example.net");
53	  const players = 12 + (h % 340);
54	  const max = players < 80 ? 100 : players < 400 ? 500 : 1000;
55	  const latency = 8 + ((h >> 3) % 58);
56	  const history = Array.from({ length: 12 }, (_, i) => latency + (((h >> (i % 7)) % 12) - 6));
57	  return {
58	    host: host || "play.example.net",
59	    port: port || 25565,
60	    online: true,
61	    version: "1.21.1",
62	    protocol: 767,
63	    playersOnline: players,
64	    playersMax: max,
65	    motd: "A Nxeon-hosted server — welcome back, builder.",
66	    latency,
67	    sample: SAMPLE_PLAYERS.slice(0, 4),
68	    history: history.map((v) => Math.max(4, v)),
69	  };
70	}
