import type { Metadata } from "next";
import { VpsLanding } from "@/components/marketing/vpstemplate/VpsLanding";
import { CONFIG_STOPS } from "@/components/marketing/vpstemplate/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { APP_URL, FaqJsonLd, ProductOffersJsonLd } from "@/components/marketing/StructuredData";

// ReviewBadges reads the live Reviews engine (DB) — render dynamically, like the
// shipped /vps page, so the hero trust strip reflects real approved reviews.
export const dynamic = "force-dynamic";

const DESCRIPTION =
  "Deploy a cloud VPS with full root access in about 47 seconds — real KVM power on enterprise NVMe (ZFS), a dedicated IPv4 + IPv6, always-on DDoS protection, and automated snapshots, from Singapore. Resize any time.";

// PREVIEW ROUTE — not a live product page. Kept out of search + sitemaps, but
// carries production-quality metadata + schema so the template ships ready.
export const metadata: Metadata = {
  title: "Cloud VPS Hosting",
  description: DESCRIPTION,
  alternates: { canonical: "/preview/vps" },
  openGraph: {
    type: "website",
    title: "Cloud VPS Hosting — full root in 47 seconds",
    description: DESCRIPTION,
    url: "/preview/vps",
  },
  robots: { index: false, follow: false },
};

/** Offers from the configurator stops — "$11.99" → 11.99. */
const OFFERS = CONFIG_STOPS.map((s) => ({
  name: `${s.tier} — ${s.ram} GB RAM · ${s.vcpu} vCPU`,
  price: Number(s.price.replace(/[^0-9.]/g, "")),
}));

const FAQ = [
  {
    q: "How fast is a Nxeon VPS deployed?",
    a: "Pick an OS or one-click app and your instance is provisioned and connect-ready in about 47 seconds — no waiting on manual setup.",
  },
  {
    q: "Do I get full root access?",
    a: "Yes. Every plan is real KVM virtualisation with dedicated resources — your own kernel, sudo, any OS, and any port. No shared babysitting.",
  },
  {
    q: "Can I resize my server later?",
    a: "Yes. Scale RAM, vCPU, and NVMe up in a couple of clicks with no migration, no reinstall, and no downtime window.",
  },
  {
    q: "What is included in the price?",
    a: "The dedicated IPv4 + IPv6, always-on DDoS filtering, automated snapshots, and full root access are all included — no setup fees and no bandwidth traps.",
  },
  {
    q: "Where are the servers located?",
    a: "On a low-latency Singapore network (SGP1) built for Asia-Pacific, with sub-10ms metro latency and 24/7 monitoring.",
  },
];

export default function Page() {
  return (
    <>
      <ProductOffersJsonLd
        name="Nxeon Cloud VPS"
        description={DESCRIPTION}
        url={`${APP_URL}/preview/vps`}
        offers={OFFERS}
      />
      <FaqJsonLd items={FAQ} />
      <VpsLanding reviewBadges={<ReviewBadges />} />
    </>
  );
}

