export const dynamic = "force-dynamic";

const DESCRIPTION =
  "Free Minecraft server status checker — see if any Java or Bedrock server is online, its player count, version, MOTD, and ping in one click. No login, nothing stored, SRV records followed automatically.";

// PREVIEW ROUTE — not a live product page. Kept out of search + sitemaps, but
// carries production-quality metadata + schema so the template ships ready.
export const metadata: Metadata = {
  title: "Minecraft Server Status Checker",
  description: DESCRIPTION,
  alternates: { canonical: "/preview/tool" },
  openGraph: {
    type: "website",
    title: "Free Minecraft Server Status Checker",
    description: DESCRIPTION,
    url: "/preview/tool",
  },
  robots: { index: false, follow: false },
};

// Tool-appropriate schema: a free, web-based utility. offers.price "0" marks it
// free; provider ties it to the Nxeon brand entity.
const SOFTWARE_JSON_LD = {
  "@context": "https://schema.org",
  "@type": "SoftwareApplication",
  name: "Minecraft Server Status Checker",
  applicationCategory: "UtilitiesApplication",
  operatingSystem: "Any (web-based)",
  url: `${APP_URL}/preview/tool`,
  description: DESCRIPTION,
  featureList: [
    "Online/offline status",
    "Live player count",
    "Server version and protocol",
    "MOTD",
    "Latency / ping",
    "SRV record resolution",
  ],
  offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
  provider: { "@type": "Organization", name: "Nxeon", url: APP_URL },
};

export default function Page() {
  return (
    <>
      <script
        type="application/ld+json"
        // JSON.stringify output is safe to inline; no user input here.
        dangerouslySetInnerHTML={{ __html: JSON.stringify(SOFTWARE_JSON_LD) }}
      />
      <ToolLanding reviewBadges={<ReviewBadges />} />
    </>
  );
}

